import stainless.annotation._
import stainless.lang._
import stainless.io._
import stainless.math.Unsigned._

/**
 * End-to-end test that the C code generated by GenC preserves the Scala
 * semantics of fixed-width integer operations:
 *  - logical right shift (`>>>`) and left shift on signed values, where C
 *    needs a detour through unsigned types to be well defined;
 *  - `Byte`/`Short` operands being promoted to `Int` before a shift;
 *  - narrowing and widening conversions between Byte, Short, Int and Long;
 *  - truncating division and remainder on negative operands, for Int and Long;
 *  - bitwise operators and mixed-width comparisons;
 *  - modular arithmetic, shifts and conversions on unsigned integers.
 * Every value is computed through a function call so that neither the Scala
 * compiler nor Stainless can constant-fold it away.
 */
object IntegerSemantics {

  @extern
  @cCode.function(
    code = """
      |void __FUNCTION__(int64_t x) {
      |  printf("%"PRIi64"\n", x);
      |}
      """,
    headerIncludes = "inttypes.h:stdio.h",
    cIncludes = ""
  )
  def printlnLong(x: Long)(implicit @ghost state: State): Unit = {
    scala.Predef.println(x)
  }

  def boolToInt(b: Boolean): Int = if (b) 1 else 0

  // ---- shifts on signed integers ----
  def lshr(x: Int, n: Int): Int = { require(0 <= n && n < 32); x >>> n }
  def shl(x: Int, n: Int): Int = { require(0 <= n && n < 32); x << n }
  def lshrLong(x: Long, n: Long): Long = { require(0 <= n && n < 64); x >>> n }
  def shlLong(x: Long, n: Long): Long = { require(0 <= n && n < 64); x << n }

  // Byte/Short operands are promoted (sign-extended) to Int before shifting.
  def byteShl(b: Byte, n: Int): Int = { require(0 <= n && n < 32); b << n }
  def byteLshr(b: Byte, n: Int): Int = { require(0 <= n && n < 32); b >>> n }
  def shortLshr(s: Short, n: Int): Int = { require(0 <= n && n < 32); s >>> n }

  // ---- conversions ----
  def toByte(x: Int): Byte = x.toByte
  def toShort(x: Int): Short = x.toShort
  def toInt(x: Long): Int = x.toInt
  def toLong(x: Int): Long = x.toLong
  def byteToInt(b: Byte): Int = b.toInt
  def byteToUnsigned(b: Byte): Int = b & 0xff
  def byteToLong(b: Byte): Long = b.toLong

  // ---- division ----
  def div(a: Int, b: Int): Int = { require(b != 0); a / b }
  def rem(a: Int, b: Int): Int = { require(b != 0); a % b }
  def divLong(a: Long, b: Long): Long = { require(b != 0); a / b }
  def remLong(a: Long, b: Long): Long = { require(b != 0); a % b }

  // ---- bitwise and comparisons ----
  def bnot(x: Int): Int = ~x
  def bitOps(x: Int, y: Int): Int = (x & y) | (x ^ y)
  def mixedCmp(b: Byte, i: Int): Boolean = b < i
  def negate(x: Int): Int = -x

  // ---- unsigned integers ----
  def addU8(a: UByte, b: UByte): UByte = a + b
  def subU32(a: UInt, b: UInt): UInt = a - b
  def mulU16(a: UShort, b: UShort): UShort = a * b
  def shrU8(a: UByte, n: UByte): UByte = { require(n < 8.toUByte); a >>> n }
  def shlU32(a: UInt, n: UInt): UInt = { require(n < 32.toUInt); a << n }
  def toUnsigned(x: Int): UInt = x.toUInt
  def toSigned(x: UInt): Int = x.toInt
  def u8ToInt(x: UByte): Int = x.toInt
  def widenU8(x: UByte): UInt = x.toUInt
  def narrowU32(x: UInt): UByte = x.toUByte

  @cCode.`export`
  def main(): Unit = {
    @ghost implicit val state = newState

    // Shifts on Int: >>> is logical, << wraps into the sign bit.
    StdOut.println(lshr(-16, 2))                      // 1073741820
    StdOut.println(lshr(-1, 31))                      // 1
    StdOut.println(lshr(-1, 0))                       // -1
    StdOut.println(shl(1, 31))                        // -2147483648
    StdOut.println(shl(2147483647, 1))                // -2
    StdOut.println(shl(-1, 20))                       // -1048576

    // Shifts on Long.
    printlnLong(shlLong(1, 40))                       // 1099511627776
    printlnLong(lshrLong(-1, 60))                     // 15
    printlnLong(shlLong(-1, 63))                      // -9223372036854775808
    printlnLong(lshrLong(shlLong(-1, 63), 63))        // 1

    // Byte/Short operands are promoted to Int before shifting.
    StdOut.println(byteShl(-1, 4))                    // -16
    StdOut.println(byteShl(100, 2))                   // 400
    StdOut.println(byteLshr(-1, 4))                   // 268435455
    StdOut.println(shortLshr(-2, 1))                  // 2147483647

    // Narrowing keeps the low bits, widening sign-extends.
    StdOut.println(byteToInt(toByte(300)))            // 44
    StdOut.println(byteToInt(toByte(-129)))           // 127
    StdOut.println(byteToInt(toByte(200)))            // -56
    StdOut.println(byteToUnsigned(toByte(200)))       // 200
    StdOut.println(toShort(70000).toInt)              // 4464
    StdOut.println(toShort(-40000).toInt)             // 25536
    StdOut.println(toInt(shlLong(1, 35) + 7))         // 7
    StdOut.println(toInt(-1L))                        // -1
    printlnLong(toLong(-1))                           // -1
    printlnLong(toLong(2147483647) + 1)               // 2147483648
    printlnLong(byteToLong(-128))                     // -128

    // Division and remainder truncate toward zero.
    StdOut.println(div(-7, 2))                        // -3
    StdOut.println(rem(-7, 2))                        // -1
    StdOut.println(div(7, -2))                        // -3
    StdOut.println(rem(7, -2))                        // 1
    StdOut.println(rem(-7, -2))                       // -1
    printlnLong(divLong(-9000000000L, 7))             // -1285714285
    printlnLong(remLong(-9000000000L, 7))             // -5

    // Bitwise operators and mixed-width comparison.
    StdOut.println(bnot(0))                           // -1
    StdOut.println(bnot(5))                           // -6
    StdOut.println(bitOps(0x0f0f, 0x00ff))            // 4095
    StdOut.println(boolToInt(mixedCmp(-1, 0)))        // 1
    StdOut.println(boolToInt(mixedCmp(127, 127)))     // 0
    StdOut.println(negate(-5))                        // 5

    // Unsigned arithmetic is modular; conversions reinterpret the bits.
    StdOut.printlnU8(addU8(250.toUByte, 10.toUByte))  // 4
    StdOut.printlnU32(subU32(0.toUInt, 1.toUInt))     // 4294967295
    StdOut.printlnU16(mulU16(300.toUShort, 300.toUShort)) // 24464
    StdOut.printlnU8(shrU8(200.toUByte, 3.toUByte))    // 25
    StdOut.printlnU32(shlU32(1.toUInt, 31.toUInt))    // 2147483648
    StdOut.printlnU32(toUnsigned(-1))                 // 4294967295
    StdOut.println(toSigned(subU32(0.toUInt, 1.toUInt))) // -1
    StdOut.println(toSigned(toUnsigned(-2147483648))) // -2147483648
    StdOut.println(u8ToInt(narrowU32(subU32(0.toUInt, 1.toUInt)))) // 255
    StdOut.printlnU32(widenU8(200.toUByte))           // 200
  }
}
